Item.method_code:
var query = this.newItem("ExampleReview", "get");
query.setID(this.getID());
var original = query.apply();

if (original.isError())
{
    return original;
}

if (!string.IsNullOrEmpty(original.getProperty("missing_info")))
{
    this.removeProperty("approved_on");
}

return this;

var rules = this.getInnovator().applyMethod("ReadReviewRules", "");

if (rules.isError())
{
    return rules;
}

var update = this.newItem("ExampleReview", "edit");
update.setID(this.getProperty("review_id"));
update.setProperty("remark", this.getProperty("remark"));
update.setProperty("approved_on", this.getProperty("approved_on"));

return update.apply();
